fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
    let peeked = self.lexer.peek().cloned();
    if let Some(Ok(t)) = &peeked {
        if predicate(t) {
            self.lexer.next();
            return Some(t.clone());
        }
    }
